function testFillTemplate() {
  const member = { firstName: "Hana", hours: 18.5 }
  console.log(fillTemplate("Thank you, {{First Name}}, for {{Hours}} hours!", member))
}

function fillTemplate(text, member) {
  const withName = text.replace("{{First Name}}", member.firstName)
  const withHours = withName.replace("{{Hours}}", String(member.hours))
  return withHours
}
